import { headers } from "next/headers";

export const dynamic = "force-dynamic";

export default async function Home() {
  const now = new Date();
  const requestHeaders = await headers();
  const userAgent = requestHeaders.get("user-agent") ?? "unknown";

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>
        Current server time: <strong>{now.toISOString()}</strong>
      </p>
      <p>Unix epoch (ms): {now.getTime()}</p>
      <p>User-Agent: {userAgent}</p>
      <p style={{ fontSize: 12, color: "#666" }}>
        This value is generated on every request because this route is opted
        out of static prerendering via{" "}
        <code>export const dynamic = &quot;force-dynamic&quot;</code>.
      </p>
    </main>
  );
}

